from sklearn.metrics import accuracy_score, r2_score

def evaluate_predictions(kind, y_true, y_pred):
    if kind == "classification":
        return round(accuracy_score(y_true, y_pred), 2)
    return round(r2_score(y_true, y_pred), 2)
